resource "kubernetes_namespace_v1" "this" {
  metadata { name = var.namespace } # "ai-agents"
}

# DB password from Vault (kvv2 infrastructure/ai-agents/temporal), synced by External Secrets.
resource "kubectl_manifest" "temporal_db_secret" {
  yaml_body = yamlencode({
    apiVersion = "external-secrets.io/v1"
    kind       = "ExternalSecret"
    metadata   = { name = "temporal-db", namespace = kubernetes_namespace_v1.this.metadata[0].name }
    spec = {
      refreshInterval = "5m"
      secretStoreRef  = { name = "vault-store", kind = "ClusterSecretStore" }
      target          = { name = "temporal-db", creationPolicy = "Owner" }
      data            = [{ secretKey = "password", remoteRef = { key = var.vault_path, property = "DB_PASSWORD" } }]
    }
  })
}

# Sandboxes reach exactly three things on inf: the broker's sandbox port, the LLM gateway and the
# OTel collector. Not envoy-internal (that would expose every internal tool) and not Temporal.
locals {
  sandbox_ports = { broker = 443, gateway = 8443, otel = 4318 }
}

resource "aws_lb" "sandbox_facing" {
  name               = "ai-agents-sandbox-facing"
  internal           = true
  load_balancer_type = "network"
  subnets            = var.inf_private_subnets
  tags               = var.tags
}

resource "aws_lb_listener" "this" {
  for_each          = local.sandbox_ports
  load_balancer_arn = aws_lb.sandbox_facing.arn
  port              = each.value
  protocol          = "TLS"
  certificate_arn   = var.acm_certificate_arn # *.ai-agents.example.com
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.this[each.key].arn # pods bound with TargetGroupBinding
  }
}
